      "root_cause": "Compute resource exhaustion in the forecast-pipeline executor",
      "mechanism": "Pipeline executor pods were OOMKilled or CPU-throttled due to peak batch load or a memory leak.",
      "statement": "Likely if the incident aligns with other midnight batch workloads competing for shared infrastructure."
    },
    {
      "root_cause": "Scheduler/orchestrator lock contention in the forecast-pipeline",
      "mechanism": "An earlier pipeline run held a lock, lease, or state marker and caused subsequent runs to block or fail.",
      "statement": "Possible when a first run does not release its lock and the retry collides with the stale run."
    },
    {
      "root_cause": "Recent configuration or deployment change in the forecast-pipeline",
      "mechanism": "A config or version change introduced an invalid parameter, feature flag, or path that caused runtime failure.",
      "statement": "Possible if a deployment or configuration change was applied shortly before the incident and then reverted."
    },
    {
      "root_cause": "Downstream storage/output dependency failure",
      "mechanism": "The pipeline failed or held while writing output because its object storage or database destination was unavailable or slow.",
      "statement": "Possible if failures occur specifically at the output commit or persistence stage."
    }
  ]
